toastEl.classList.remove('show');
}, 2400);
}
window.showToast = showToast;

var videoEl = document.getElementById('tiffyVideo');
var playBtn = document.getElementById('playBtn');
var muteBtn = document.getElementById('muteBtn');
var isPlaying = false;

function tryAutoplay() {
videoEl.muted = true;
var p = videoEl.play();
if (p !== undefined) {
p.then(function() {
isPlaying = true;
playBtn.textContent = '⏸️';
muteBtn.textContent = '🔇';
}).catch(function() {
isPlaying = false;
playBtn.textContent = '▶️';
});
}
}
tryAutoplay();

function togglePlay() {
if (isPlaying) {
videoEl.pause();
isPlaying = false;
playBtn.textContent = '▶️';
} else {
videoEl.play();
isPlaying = true;
playBtn.textContent = '⏸️';
}
}
window.togglePlay = togglePlay;

function toggleMute() {
videoEl.muted = !videoEl.muted;
muteBtn.textContent = videoEl.muted ? '🔇' : '🔊';
}
window.toggleMute = toggleMute;

