function updateClock() {
var now = new Date();
var h = String(now.getHours()).padStart(2, '0');
var m = String(now.getMinutes()).padStart(2, '0');
var s = String(now.getSeconds()).padStart(2, '0');
clockEl.textContent = h + ':' + m + ':' + s;
}
updateClock();
setInterval(updateClock, 1000);

var glitterContainer = document.getElementById('glitterContainer');
var glitterColors = ['#FF2D78', '#FFB3D1', '#F5C842', '#FF6BA8', '#FFEAF2', '#FFF0A8', '#E8185A', '#ffffff'];

function spawnGlitter(e) {
var count = 18;
var x = e.clientX || (window.innerWidth / 2);
var y = e.clientY || (window.innerHeight / 2);
for (var i = 0; i < count; i++) {
(function(idx) {
setTimeout(function() {
var p = document.createElement('div');
p.className = 'glitter-particle';
var angle = (idx / count) * 360;
var radius = 40 + Math.random() * 60;
var rad = angle * (Math.PI / 180);
var tx = x + Math.cos(rad) * radius;
var ty = y + Math.sin(rad) * radius;
var color = glitterColors[Math.floor(Math.random() * glitterColors.length)];
var size = 4 + Math.random() * 8;
p.style.cssText = 'left:' + tx + 'px;top:' + ty + 'px;width:' + size + 'px;height:' + size + 'px;background:' + color + ';box-shadow:0 0 6px ' + color + ';';
p.style.animationDuration = (0.6 + Math.random() * 0.6) + 's';
glitterContainer.appendChild(p);
p.addEventListener('animationend', function() {
if (p.parentNode) p.parentNode.removeChild(p);
});
}, idx * 30);
})(i);
}
}
window.spawnGlitter = spawnGlitter;

if ('serviceWorker' in navigator) {
