<script>
(function () {
var video = document.getElementById('tiffyVideo');
var playBtn = document.getElementById('playBtn');
var playIcon = document.getElementById('playIcon');
var playLabel = document.getElementById('playLabel');
var muteBtn = document.getElementById('muteBtn');
var progressFill = document.getElementById('progressFill');
var progressTrack = document.getElementById('progressTrack');
var timeCurrentEl = document.getElementById('timeCurrentEl');
var timeDurationEl = document.getElementById('timeDurationEl');
var glitterContainer = document.getElementById('glitterContainer');
var videoContainer = document.getElementById('videoContainer');
var isPlaying = false;
var glitterColors = ['#FF2D78', '#FFB3D1', '#F5C842', '#FF6BA8', '#FFEAF2', '#FFF0A8', '#E8185A', '#ffffff', '#FF2D78'];

function formatTime(s) {
if (isNaN(s) || s < 0) return '0:00';
var m = Math.floor(s / 60);
var sec = Math.floor(s % 60);
return m + ':' + (sec < 10 ? '0' : '') + sec;
}

function setPlaying(state) {
isPlaying = state;
playIcon.textContent = isPlaying ? '⏸' : '▶';
playLabel.textContent = isPlaying ? 'Szünet' : 'Lejátszás';
}

function tryAutoplay() {
video.muted = true;
muteBtn.textContent = '🔇';
var p = video.play();
if (p !== undefined) {
p.then(function () {
setPlaying(true);
}).catch(function () {
setPlaying(false);
});
}
}

tryAutoplay();

video.addEventListener('play', function () { setPlaying(true); });
video.addEventListener('pause', function () { setPlaying(false); });
video.addEventListener('ended', function () { setPlaying(false); });

video.addEventListener('timeupdate', function () {
if (video.duration && !isNaN(video.duration)) {
var pct = (video.currentTime / video.duration) * 100;
progressFill.style.width = pct + '%';
timeCurrentEl.textContent = formatTime(video.currentTime);
}
});

video.addEventListener('loadedmetadata', function () {
timeDurationEl.textContent = formatTime(video.duration);
});

video.addEventListener('durationchange', function () {
timeDurationEl.textContent = formatTime(video.duration);
});

function togglePlay() {
if (isPlaying) {
video.pause();
} else {
var p = video.play();
if (p !== undefined) {
p.catch(function () {});
}
}
spawnGlitterCenter();
}

function toggleMute() {
video.muted = !video.muted;
muteBtn.textContent = video.muted ? '🔇' : '🔊';
}

function toggleFullscreen() {
if (video.requestFullscreen) {
video.requestFullscreen();
} else if (video.webkitRequestFullscreen) {
video.webkitRequestFullscreen();
} else if (video.webkitEnterFullscreen) {
video.webkitEnterFullscreen();
}
}

progressTrack.addEventListener('click', function (e) {
var rect = progressTrack.getBoundingClientRect();
var ratio = (e.clientX - rect.left) / rect.width;
if (video.duration && !isNaN(video.duration)) {
video.currentTime = ratio * video.duration;
}
});

progressTrack.addEventListener('touchstart', function (e) {
e.preventDefault();
handleProgressTouch(e.touches[0]);
}, { passive: false });

progressTrack.addEventListener('touchmove', function (e) {
e.preventDefault();
handleProgressTouch(e.touches[0]);
}, { passive: false });

function handleProgressTouch(touch) {
var rect = progressTrack.getBoundingClientRect();
var ratio = Math.max(0, Math.min(1, (touch.clientX - rect.left) / rect.width));
if (video.duration && !isNaN(video.duration)) {
video.currentTime = ratio * video.duration;
}
}

function spawnGlitter(x, y) {
var count = 20;
for (var i = 0; i < count; i++) {
(function (idx) {
setTimeout(function () {
var p = document.createElement('div');
p.className = 'glitter-particle';
var angle = (idx / count) * 360 + Math.random() * (360 / count);
var radius = 30 + Math.random() * 70;
var rad = angle * (Math.PI / 180);
var tx = x + Math.cos(rad) * radius;
var ty = y + Math.sin(rad) * radius;
var color = glitterColors[Math.floor(Math.random() * glitterColors.length)];
var size = 4 + Math.random() * 8;
p.style.cssText = 'left:' + tx + 'px;top:' + ty + 'px;width:' + size + 'px;height:' + size + 'px;background:' + color + ';box-shadow:0 0 6px ' + color + ';';
p.style.animationDuration = (0.5 + Math.random() * 0.7) + 's';
glitterContainer.appendChild(p);
p.addEventListener('animationend', function () {
if (p.parentNode) p.parentNode.removeChild(p);
});
}, idx * 25);
})(i);
}
}

function spawnGlitterCenter() {
var rect = videoContainer.getBoundingClientRect();
var cx = rect.left + rect.width / 2;
var cy = rect.top + rect.height / 2;
spawnGlitter(cx, cy);
}

videoContainer.addEventListener('click', function (e) {
togglePlay();
spawnGlitter(e.clientX, e.clientY);
});

window.togglePlay = togglePlay;
window.toggleMute = toggleMute;
window.toggleFullscreen = toggleFullscreen;

if ('serviceWorker' in navigator) {
var swBlob = new Blob([
'var CACHE="tiffy-v2";',
'self.addEventListener("install",function(e){',
'e.waitUntil(caches.open(CACHE).then(function(c){return c.addAll(["/"]);}).catch(function(){}));',
'});',
'self.addEventListener("fetch",function(e){',
'e.respondWith(caches.match(e.request).then(function(r){return r||fetch(e.request);}));',
'});'
], { type: 'application/javascript' });
var swURL = URL.createObjectURL(swBlob);
navigator.serviceWorker.register(swURL).catch(function () {});
}
})();
</script>
</body>
